require __DIR__.'/../../config.php';if(DB_NAME!=='maakit_jaanch')throw new RuntimeException('CI database only');require __DIR__.'/../../school/inc.php';$db=sch_db();
function ff($ok,$why){if(!$ok)throw new RuntimeException('Faculty: '.$why);}
function fi(){return sprintf('%s-%s-%s-%s-%s',bin2hex(random_bytes(4)),bin2hex(random_bytes(2)),bin2hex(random_bytes(2)),bin2hex(random_bytes(2)),bin2hex(random_bytes(6)));}
function ft($uid,$role,$tid){$db=sch_db();$db->prepare('INSERT INTO sch_users(uid,role,tid) VALUES(?,?,?) ON DUPLICATE KEY UPDATE role=VALUES(role),tid=VALUES(tid)')->execute([$uid,$role,$tid]);$t=bin2hex(random_bytes(32));$db->prepare('INSERT INTO sch_sessions(token_hash,uid,expires_at) VALUES(?,?,DATE_ADD(NOW(),INTERVAL 1 DAY))')->execute([hash('sha256',$t),$uid]);return $t;}
