 [$c]=fh('save',$T,['version'=>0,'profile'=>$profile,'submit'=>true]);ff($c===200,'Own profile save');[$c]=fh('save',$T,['version'=>0,'profile'=>$profile]);ff($c===409,'Stale version accepted');[$c,,$raw]=fh('state',$X,null,'FF');ff($c===200&&!str_contains($raw,'PRIVATE_EMERGENCY'),'Teacher read another profile');
 [$c]=fh('review',$T,['version'=>1,'decision'=>'approve']);ff($c===403,'Self approval');
