 sch_rec_put('alloc','main',[['c'=>'6th','s'=>'Maths','t'=>'FF'],['c'=>'7th','s'=>'Science','t'=>'FF']],'principal');sch_rec_put('grid','main',['6th'=>[[0]],'7th'=>[[1]]],'principal');[$c]=fh('review',$P,['version'=>1,'decision'=>'approve'],'FF');ff($c===409,'Collision ignored');sch_rec_put('alloc','main',[['c'=>'6th','s'=>'Maths','t'=>'FF']],'principal');sch_rec_put('grid','main',['6th'=>[[0]]],'principal');
 [$c]=fh('review',$P,['version'=>1,'decision'=>'approve'],'FF');ff($c===200,'Principal approval failed');[$c,$s]=fh('state',$T);$idToken=$s['approved']['idToken'];ff($s['approved']['timetableLinked']===true,'Timetable link missing');[$c,$v,$raw]=fh('verify&token='.$idToken);ff($c===200&&$v['valid']&&!str_contains($raw,'PRIVATE_EMERGENCY')&&!str_contains($raw,'9999999999'),'ID verification leaked private data');
 [$c,$d,$raw]=fh('directory&scope=website');ff($c===200&&count($d['profiles'])===1&&str_contains($raw,'PUBLIC_BIO_SYNTHETIC')&&!str_contains($raw,'PRIVATE_EMERGENCY'),'Public directory privacy');[$c,$d]=fh('directory',$A);ff($c===200&&count($d['profiles'])===1,'Linked parent profile missing');
 [$c]=fh('credential',$T,['id'=>fi(),'type'=>'CPD','title'=>'Old training','issuer'=>'Synthetic provider','reference'=>'Old session evidence','date'=>'2025-10-01','hours'=>5]);ff($c===400,'Prior-session CPD counted in this session');
 [$c]=fh('credential',$T,['id'=>$cred,'type'=>'CPD','title'=>'Synthetic training','issuer'=>'Synthetic provider','reference'=>'Check synthetic evidence in office','date'=>'2026-10-01','hours'=>5]);ff($c===200,'Credential save');[$c,$s]=fh('state',$T);ff($s['metrics']['cpdVerified']==0&&$s['metrics']['cpdPending']==5,'Unverified CPD counted');[$c]=fh('credentialReview',$T,['credential'=>$cred,'status'=>'Verified']);ff($c===403,'Teacher verified own CPD');[$c]=fh('credentialReview',$P,['credential'=>$cred,'status'=>'Verified'],'FF');ff($c===200,'Principal credential verification');[$c,$s]=fh('state',$T);ff($s['metrics']['cpdVerified']==5&&$s['metrics']['onTimeStreak']===null,'Real metrics failed');
 [$c]=fh('service',$T,['allowance'=>12,'used'=>2]);ff($c===403,'Teacher edited leave allowance');[$c]=fh('service',$P,['allowance'=>12,'used'=>2],'FF');ff($c===200,'Leave ledger update');[$c,$s]=fh('state',$T);ff($s['metrics']['clBalance']==10,'Leave balance failed');
 [$c]=fh('reflection',$T,['text'=>'PRIVATE_REFLECTION_FF']);ff($c===200,'Reflection save');[$c,,$raw]=fh('reflection',$P,null,'FF');ff(!str_contains($raw,'PRIVATE_REFLECTION_FF'),'Principal read reflection');
 // A photo is re-encoded privately and scoped to its owner.
